import React, { useState, useEffect } from 'react';
import NavigationBar from './NavigationBar';
import { Container, Row, Col, Form, Button } from 'react-bootstrap';
import api from './Axios';

function Profile() {
  // Retrieve initial values from localStorage (adjust keys as you set them during login)
  const initialProfile = {
    username: localStorage.getItem("username") || "",
    email: localStorage.getItem("userEmail") || "",
    password: localStorage.getItem("password") || ""
  };

  const [profile, setProfile] = useState(initialProfile);
  const [editing, setEditing] = useState(false);

  // Update local state if localStorage changes (e.g., on Save)
  useEffect(() => {
    setProfile({
      username: localStorage.getItem("username") || "",
      email: localStorage.getItem("userEmail") || "",
      password: localStorage.getItem("password") || ""
    });
  }, []);

  // Handle form field changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({ ...prev, [name]: value }));
  };

  // Save updated profile via PUT endpoint
  const handleSave = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("authToken");
      // Call the backend update endpoint
      const response = await api.put("/api/users/profile/update", profile, {
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer " + token
        }
      });
      if (response.status === 200) {
        alert("Profile updated successfully.");
        setEditing(false);
        // Update localStorage with the new profile values
        localStorage.setItem("username", response.data.username);
        localStorage.setItem("userEmail", response.data.email);
        localStorage.setItem("password", response.data.password);
      } else {
        alert("Failed to update profile.");
      }
    } catch (error) {
      console.error("Error updating profile:", error);
      alert("Error updating profile: " + error.message);
    }
  };

  // Cancel editing: revert to values stored in localStorage
  const handleCancel = () => {
    setEditing(false);
    setProfile({
      username: localStorage.getItem("username") || "",
      email: localStorage.getItem("userEmail") || "",
      password: localStorage.getItem("password") || ""
    });
  };

  return (
    <div>
      <NavigationBar />
      <Container style={{ width: "100%", paddingTop: "1.5rem" }}>
        <Row>
          <Col>
            <h1>Profile</h1>
            <Form onSubmit={handleSave}>
              <Form.Group controlId="username" className="mb-3">
                <Form.Label>Username</Form.Label>
                <Form.Control 
                  type="text" 
                  name="username" 
                  value={profile.username} 
                  onChange={handleChange} 
                  readOnly={!editing}
                />
              </Form.Group>
              <Form.Group controlId="email" className="mb-3">
                <Form.Label>Email</Form.Label>
                <Form.Control 
                  type="email" 
                  name="email" 
                  value={profile.email} 
                  readOnly // Email remains read-only
                />
              </Form.Group>
              <Form.Group controlId="password" className="mb-3">
                <Form.Label>Password</Form.Label>
                <Form.Control 
                  type="password" 
                  name="password" 
                  value={profile.password} 
                  onChange={handleChange} 
                  readOnly={!editing}
                />
              </Form.Group>
              {editing ? (
                <div>
                  <Button variant="primary" type="submit" className="me-2">
                    Save Changes
                  </Button>
                  <Button variant="secondary" onClick={handleCancel}>
                    Cancel
                  </Button>
                </div>
              ) : (
                <Button variant="primary" onClick={() => setEditing(true)}>
                  Edit Profile
                </Button>
              )}
            </Form>
          </Col>
        </Row>
      </Container>
    </div>
  );
}

export default Profile;
